import{_ as e,o as s,c as t,a2 as o}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"六月","description":"","frontmatter":{"title":"六月","date":"2026-11-08T00:00:00.000Z","seq":17,"categories":["美文","诗经"],"collection":"《诗经 · 小雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·小雅/六月.md","filePath":"blogs/诗经·小雅/六月.md"}'),p={name:"blogs/诗经·小雅/六月.md"};function r(c,a,l,n,_,i){return s(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="六月" tabindex="-1">六月 <a class="header-anchor" href="#六月" aria-label="Permalink to &quot;六月&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　南有嘉鱼之什</p><div class="poem"><p class="poem-stanza">六月栖栖，戎车既饬。四牡骙骙，载是常服。玁狁孔炽，我是用急。王于出征，以匡王国。</p><p class="poem-stanza">比物四骊，闲之维则。维此六月，既成我服。我服既成，于三十里。王于出征，以佐天子。</p><p class="poem-stanza">四牡修广，其大有颙。薄伐玁狁，以奏肤公。有严有翼，共武之服。共武之服，以定王国。</p><p class="poem-stanza">玁狁匪茹，整居焦获。侵镐及方，至于泾阳。织文鸟章，白旆央央。元戎十乘，以先启行。</p><p class="poem-stanza">戎车既安，如轾如轩。四牡既佶，既佶且闲。薄伐玁狁，至于大原。文武吉甫，万邦为宪。</p><p class="poem-stanza">吉甫燕喜，既多受祉。来归自镐，我行永久。饮御诸友，炰鳖脍鲤。侯谁在矣？张仲孝友。</p></div>',3)])])}const u=e(p,[["render",r]]);export{d as __pageData,u as default};
